            data["threads"][thread_id] = thread
        data["runs"][run["id"]] = run
        app.state.service.event(data, "CHALLENGE_REQUESTED", thread["entity_id"], None, dict(body, run_id=run["id"]), (request.actor_id, request.actor_role), request.rationale)
